/** Validate an exported FLUME model before allocating GPU buffers or interpreting binary tensor offsets. */
export function validateModel(m, bytes) {
  if (
    m.dtype !== 'float16' ||
    m.total_bytes !== bytes ||
    m.grid?.horizontal_spacing_m !== 4 ||
    m.grid?.vertical_spacing_m !== 1.5
  )
    throw new Error('Model bytes/grid spacing do not match FLUME.')
  if (
    m.model?.input_channels !== 24 ||
    m.model?.output_channels !== 5 ||
    m.inference?.patch?.join() !== '64,64' ||
    m.target?.channel_names?.join() !== 'u,w,v,T,TKE'
  )
    throw new Error('Unsupported model shape/channel order.')
  for (const t of Object.values(m.tensors ?? {})) {
    if (
      !Number.isInteger(t.offset) ||
      t.offset < 0 ||
      t.offset % 2 ||
      !Number.isInteger(t.count) ||
      t.count <= 0 ||
      t.offset + t.count * 2 > bytes ||
      !Array.isArray(t.shape) ||
      t.shape.some((n) => !Number.isInteger(n) || n < 1) ||
      t.shape.reduce((a, b) => a * b, 1) !== t.count
    )
      throw new Error('Invalid model tensor bounds.')
  }
  if (
    !Object.keys(m.tensors ?? {}).length ||
    !Number.isFinite(m.wind?.reference_speed_m_s) ||
    m.wind.reference_speed_m_s <= 0
  )
    throw new Error('Invalid model metadata.')
}

/** Accept the full FNO output; keep diagnostic masks and replace only non-finite channels for rendering/export. */
export function preparePrediction(p) {
  if (
    !Number.isInteger(p.width) ||
    !Number.isInteger(p.height) ||
    p.width < 1 ||
    p.height < 1 ||
    p.values.length !== p.width * p.height * 5 ||
    p.solid.length !== p.width * p.height
  )
    throw new Error('Invalid prediction shape.')
  for (let cell = 0; cell < p.solid.length; cell++) {
    for (let ch = 0; ch < 5; ch++) {
      if (Number.isFinite(p.values[cell * 5 + ch])) continue
      p.solid[cell] = 2
      // Zero placeholders avoid NaN bleeding through interpolation without discarding the other returned channels.
      p.values[cell * 5 + ch] = 0
    }
  }
}
