<!-- Nested settings belong to the page controller; this HUD edits that shared draft, not the prop reference. -->
<script setup>
/* eslint vue/no-mutating-props: ['error', { shallowOnly: true }] */
import { computed, ref } from 'vue'
const props = defineProps({
  settings: { type: Object, required: true },
  grid: { type: Object, default: null },
  runner: { type: Object, default: null },
  error: { type: String, default: '' },
  locked: Boolean,
})
defineEmits(['run'])
const dial = ref(null)
const radians = computed(() => (Number(props.settings.directionDeg) * Math.PI) / 180)
const ready = computed(() => Boolean(props.grid) && !props.locked)
function point(event) {
  if (!ready.value) return
  if (event.type === 'pointermove' && !event.buttons) return
  if (event.type === 'pointerdown') event.currentTarget.setPointerCapture(event.pointerId)
  const rect = dial.value.getBoundingClientRect()
  props.settings.directionDeg =
    (Math.round(
      (Math.atan2(-(event.clientY - rect.top - rect.height / 2), event.clientX - rect.left - rect.width / 2) * 180) /
        Math.PI,
    ) +
      360) %
    360
}
function keyboard(event) {
  if (!ready.value) return
  const delta =
    event.key === 'ArrowRight' || event.key === 'ArrowUp'
      ? 1
      : event.key === 'ArrowLeft' || event.key === 'ArrowDown'
        ? -1
        : 0
  if (delta) {
    event.preventDefault()
    props.settings.directionDeg = (Number(props.settings.directionDeg) + delta + 360) % 360
  }
}
</script>
<template>
  <!-- Compact two-column inputs; the original dial and automatic rerun policy are kept. -->
  <div class="wind">
    <div class="conditions">
      <label class="condition"
        ><span>Slice height <small>m</small></span>
        <input
          v-model.number="settings.heightM"
          class="num"
          type="number"
          min="0.75"
          max="239.25"
          step="1.5"
          aria-label="Slice height (m)"
          :disabled="!ready"
        />
        <input
          v-model.number="settings.heightM"
          class="range"
          type="range"
          min="0.75"
          max="239.25"
          step="1.5"
          aria-label="Slice height"
          :disabled="!ready"
        />
      </label>
      <label class="condition"
        ><span>Wind speed <small>m/s</small></span>
        <input
          v-model.number="settings.speedMps"
          class="num"
          type="number"
          min="0.5"
          max="20"
          step="0.1"
          aria-label="Reference wind speed (m/s)"
          :disabled="!ready"
        />
        <input
          v-model.number="settings.speedMps"
          class="range"
          type="range"
          min="0.5"
          max="20"
          step="0.1"
          aria-label="Wind speed"
          :disabled="!ready"
        />
      </label>
    </div>
    <div class="direction">
      <svg
        ref="dial"
        class="dial"
        viewBox="0 0 160 160"
        role="slider"
        tabindex="0"
        aria-label="Wind towards direction"
        aria-valuemin="0"
        aria-valuemax="359"
        :aria-valuenow="settings.directionDeg"
        :aria-disabled="!ready || undefined"
        @pointerdown.prevent="point"
        @pointermove="point"
        @keydown="keyboard"
      >
        <circle cx="80" cy="80" r="52" fill="none" stroke="currentColor" opacity=".28" stroke-width="2" />
        <text x="80" y="16" text-anchor="middle">90°</text>
        <text x="146" y="84" text-anchor="middle">0°</text>
        <text x="80" y="152" text-anchor="middle">270°</text>
        <text x="14" y="84" text-anchor="middle">180°</text>
        <line
          :x1="80 - Math.cos(radians) * 30"
          :y1="80 + Math.sin(radians) * 30"
          :x2="80 + Math.cos(radians) * 42"
          :y2="80 - Math.sin(radians) * 42"
          stroke="#64d2ff"
          stroke-width="3.5"
          stroke-linecap="round"
        />
        <circle :cx="80 + Math.cos(radians) * 42" :cy="80 - Math.sin(radians) * 42" r="5" fill="#64d2ff" />
      </svg>
      <div class="bearing">
        <label class="condition"
          ><span>Wind towards <small>°</small></span>
          <input
            v-model.number="settings.directionDeg"
            class="num"
            type="number"
            step="1"
            aria-label="Wind towards (°)"
            :disabled="!ready"
          />
        </label>
        <div class="cardinals">
          <VaButton
            v-for="item in [
              { text: 'E', value: 0 },
              { text: 'N', value: 90 },
              { text: 'W', value: 180 },
              { text: 'S', value: 270 },
            ]"
            :key="item.text"
            size="small"
            preset="secondary"
            :disabled="!ready"
            :aria-label="'Wind towards ' + item.text"
            @click="settings.directionDeg = item.value"
            >{{ item.text }}</VaButton
          >
        </div>
      </div>
    </div>
    <!-- <p v-if="grid" class="hint">{{ grid.nx }} × {{ grid.ny }} cells · tallest {{ grid.statistics.maximumHeightM }} m</p>
    <p v-else class="hint">Accept a simulation area first.</p> -->
    <VaAlert v-if="error" color="danger">{{ error }}</VaAlert>
    <VaAlert v-if="runner?.state.error" color="danger">{{ runner.state.error }}</VaAlert>
    <div v-if="runner?.state.busy" class="busy">
      <VaProgressBar :model-value="runner.state.progress * 100" :indeterminate="runner.state.progress === 0" />
      <p role="status">{{ runner.state.stage }}</p>
    </div>
    <VaButton block :disabled="!ready" :loading="runner?.state.busy" aria-label="Run prediction" @click="$emit('run')"
      >Run prediction</VaButton
    >
    <!-- <p class="hint">Height/direction re-run automatically · speed updates the existing field.</p> -->
  </div>
</template>
