<!-- Nested settings belong to the page controller; this HUD edits that shared draft, not the prop reference. -->
<script setup>
/* eslint vue/no-mutating-props: ['error', { shallowOnly: true }] */
import { computed } from 'vue'
import { VARIABLES, colour } from './field.js'
const props = defineProps({
  display: { type: Object, required: true },
  legend: { type: Object, default: null },
  prediction: { type: Object, default: null },
})
const ramp = computed(() => VARIABLES.find((v) => v.id === props.display.variable)?.ramp ?? 'turbo')
const gradient = computed(
  () =>
    'linear-gradient(to right,' +
    Array.from({ length: 17 }, (_, i) => {
      const c = colour(ramp.value, i / 16)
      return 'rgb(' + c.join(',') + ') ' + (i * 100) / 16 + '%'
    }).join(',') +
    ')',
)
</script>
<template>
  <!-- Display controls sit below wind inputs inside the Configuration HUD. -->
  <div class="display-settings">
    <p v-if="!prediction" class="hint">Run a prediction to inspect the field.</p>
    <template v-else>
      <div class="variables" role="group" aria-label="Field">
        <button
          v-for="item in VARIABLES"
          :key="item.id"
          type="button"
          :aria-pressed="display.variable === item.id"
          @click="display.variable = item.id"
        >
          {{ item.label }}
        </button>
      </div>

      <div class="row">
        <span class="unit">particles</span>
        <select v-model="display.particles" aria-label="Particles">
          <option value="white">white, over the field</option>
          <option value="tinted">coloured, no field</option>
          <option value="off">off</option>
        </select>
      </div>

      <VaSwitch
        v-model="display.paused"
        class="display-toggle"
        label="Pause particles"
        aria-label="Pause particles"
        size="small"
      />

      <VaSwitch
        v-model="display.showSurroundings"
        class="display-toggle"
        label="Show surrounding buildings"
        aria-label="Show surrounding buildings"
        size="small"
      />

      <div v-if="legend" class="legend">
        <div class="legend-top">
          <strong>{{ legend.legend }}</strong>
          <span>{{ legend.unit }}</span>
        </div>
        <div class="colorbar" :style="{ background: gradient }" />
        <div class="legend-range">
          <span>{{ legend.low.toFixed(2) }}</span>
          <span>{{ legend.high.toFixed(2) }}</span>
        </div>
      </div>

      <p class="hint">{{ prediction.patchCount }} patches · {{ (prediction.milliseconds / 1000).toFixed(1) }} s</p>
    </template>
  </div>
</template>

