import CityHud from '../city/components/CityHud.vue'
import RegionHud from './selection/RegionHud.vue'
import WindSettingsHud from './wind/WindSettingsHud.vue'
import DisplaySettingsHud from './result/DisplaySettingsHud.vue'
import DownloadsHud from './result/DownloadsHud.vue'
import 'mapbox-gl/dist/mapbox-gl.css'
import '@mapbox/mapbox-gl-geocoder/dist/mapbox-gl-geocoder.css'
import '@mapbox/mapbox-gl-draw/dist/mapbox-gl-draw.css'
const flume = useFlumeCity()
const { mapElement, ready, initialized, state, draft, display, region, runner, locked, regionLocked } = flume
const { controlsElement, controlsVisible, mapStyle, mapStyles } = flume.controls
</script>
<template>
  <!-- Map is always the full-size background; compact CityHud cards float above it. -->
  <section class="flume-page" aria-label="Flume City wind prediction" @keydown.esc="region.stopSelection">
    <div ref="mapElement" class="flume-map" aria-label="Flume City map" />
    <aside v-show="initialized" ref="controlsElement" class="mapboxgl-ctrl flume-map-actions">
      <VaDropdown placement="left-start" :close-on-content-click="false">
        <template #anchor><VaButton size="small" icon="mso-layers" aria-label="Flume basemap" /></template>
        <VaDropdownContent
          ><VaSelect
            v-model="mapStyle"
            label="Basemap"
            :options="mapStyles"
            text-by="title"
            value-by="value"
            :disabled="locked"
        /></VaDropdownContent>
      </VaDropdown>
      <VaButton
        size="small"
        :icon="controlsVisible ? 'mso-visibility_off' : 'mso-visibility'"
        :aria-label="controlsVisible ? 'Hide Flume controls' : 'Show Flume controls'"
        @click="controlsVisible = !controlsVisible"
      />
    </aside>
    <div v-show="controlsVisible" class="flume-hud-stack">
      <header class="flume-heading">
        <h1>Flume City</h1>
        <p>Urban wind simulation</p>
      </header>
      <!-- Region selection and source loading stay in the first HUD. -->
      <CityHud title="1 · Simulation area" :inert="regionLocked" :collapsed="state.step > 0">
        <RegionHud :region="region" :ready="ready" :locked="regionLocked" @continue="flume.acceptRegion" />
      </CityHud>
      <!-- All simulation and display settings share one collapsible HUD. -->
      <CityHud title="2 · Configuration" :collapsed="state.step === 0">
        <WindSettingsHud
          :settings="draft"
          :grid="state.grid"
          :runner="runner"
          :error="state.error"
          :locked="locked"
          @run="flume.run"
        />
        <template v-if="runner.state.prediction">
          <VaDivider />
          <DisplaySettingsHud :display="display" :legend="state.legend" :prediction="runner.state.prediction" />
        </template>
      </CityHud>
      <!-- Export actions and download feedback have their own HUD. -->
      <CityHud title="3 · Downloads" :collapsed="!state.grid">
        <DownloadsHud
          :grid="state.grid"
          :prediction="runner.state.prediction"
          :downloading="state.downloading"
          :locked="runner.state.downloading"
          :predicting="runner.state.busy"
          :error="state.downloadError"
          @download="flume.download"
        />
      </CityHud>
      <VaAlert v-if="state.error && !state.grid" color="danger">{{ state.error }}</VaAlert>
      <!-- <div v-if="region.state.snapshot?.warnings.length" class="flume-notes">
        <p v-for="warning in region.state.snapshot.warnings" :key="warning">{{ warning }}</p>
      </div> -->
    </div>
    <div v-if="!ready && !state.error" class="flume-status">
      <VaProgressBar indeterminate aria-label="Loading Flume map" />
    </div>
  </section>
</template>
