import { markRaw, onBeforeUnmount, reactive, watch } from 'vue'
import MapboxDraw from '@mapbox/mapbox-gl-draw'
import { createRegion, createPolygonRegion, selectBuildings } from './regionData.js'
import { makeUnprojector } from '../../preprocessing/stl-converter/geojsonToStl.js'
import { createBuildingPreview, showBuildingPreview } from './buildingPreview.js'
import { loadRegionTiles } from './buildingTiles.js'
const DOMAIN = 'flume-region-domain'

/** Owns free-polygon drawing and cancellable numerical tile capture. The camera never determines data detail. */
export function useFlumeRegion({ getMap, ready, onChange, accessToken }) {
  const state = reactive({
    source: 'concordia',
    drawing: false,
    loading: false,
    progress: 0,
    region: null,
    snapshot: null,
    loadedArea: null,
    error: '',
  })
  let draw = null,
    disposed = false,
    capture = null,
    revision = 0,
    cache = null
  function invalidate(keepLoadedArea = false) {
    revision++
    capture?.abort()
    if (!keepLoadedArea) {
      cache = null
      state.loadedArea = null
    }
    state.snapshot = null
    onChange?.()
  }
  function paint() {
    const map = getMap()
    if (!map || !ready.value) return
    showBuildingPreview(map, cache?.preview)
    const data = {
      type: 'FeatureCollection',
      features: state.region ? [state.region.polygon] : cache ? [cache.area.polygon] : [],
    }
    if (!data.features.length) {
      if (map.getLayer(DOMAIN)) map.removeLayer(DOMAIN)
      if (map.getSource(DOMAIN)) map.removeSource(DOMAIN)
      return
    }
    if (map.getSource(DOMAIN)) map.getSource(DOMAIN).setData(data)
    else {
      map.addSource(DOMAIN, { type: 'geojson', data })
      map.addLayer({
        id: DOMAIN,
        type: 'line',
        source: DOMAIN,
        paint: { 'line-color': '#a8b8cc', 'line-width': 1.5, 'line-dasharray': [4, 3] },
      })
    }
  }
  function setSelection(feature) {
    // The first drawing can use preloaded detail; editing an existing region starts fresh.
    invalidate(!state.region && !state.snapshot)
    state.error = ''
    try {
      state.region = markRaw(createPolygonRegion(feature))
    } catch (error) {
      state.region = null
      state.error = error.message
    }
    paint()
  }
  function readDrawing(event) {
    if (disposed || !draw) return
    const newest = event.features?.at(-1)
    if (event.type === 'draw.create' && newest)
      for (const feature of draw.getAll().features) if (feature.id !== newest.id) draw.delete(feature.id)
    const feature = draw.getAll().features.find((f) => f.geometry.type === 'Polygon')
    if (feature) setSelection(feature)
    else {
      invalidate()
      state.region = null
      paint()
    }
    state.drawing = false
  }
  function drawMode(event) {
    state.drawing = event.mode === 'draw_polygon' || event.mode === 'direct_select'
  }
  function ensureDraw() {
    const map = getMap()
    if (!map || !ready.value) throw new Error('Wait for the map to load.')
    if (!draw) {
      draw = new MapboxDraw({ displayControlsDefault: false, controls: {}, boxSelect: false })
      map.addControl(draw, 'bottom-left')
      for (const event of ['draw.create', 'draw.update', 'draw.delete']) map.on(event, readDrawing)
      map.on('draw.modechange', drawMode)
      for (const layer of map.getStyle().layers)
        if (layer.id.startsWith('gl-draw-')) {
          if (layer.type === 'fill') {
            map.setPaintProperty(layer.id, 'fill-color', '#ffd000')
            map.setPaintProperty(layer.id, 'fill-opacity', 0.1)
          }
          if (layer.type === 'line') map.setPaintProperty(layer.id, 'line-color', '#ffd000')
        }
      if (state.region?.selection) draw.add(state.region.selection)
    }
    return draw
  }
  function stopSelection() {
    if (draw) draw.changeMode('simple_select')
    state.drawing = false
  }
  function startSelection() {
    if (state.loading) return
    try {
      const tool = ensureDraw()
      getMap().stop()
      invalidate(!state.region && !state.snapshot)
      state.region = null
      tool.deleteAll()
      paint()
      tool.changeMode('draw_polygon')
      state.drawing = true
      state.error = ''
    } catch (error) {
      state.error = error.message
    }
  }
  function clearSelection() {
    getMap()?.stop()
    detachDraw()
    invalidate()
    state.region = null
    state.error = ''
    paint()
  }

  /** Fit the full computational area; detailed tile loading remains independent of this display zoom. */
  function fitArea(area) {
    const map = getMap()
    const width = map.getCanvas().clientWidth
    map.resize?.()
    map.fitBounds([area.bounds.slice(0, 2), area.bounds.slice(2, 4)], {
      padding: width >= 640 ? { top: 40, bottom: 40, left: Math.min(320, width * 0.35), right: 40 } : 32,
      pitch: 0,
      bearing: 0,
      duration: 500,
      retainPadding: false,
    })
  }

  /** Reuse detailed features for enclosed polygons; never refetch merely because the camera zoom changed. */
  async function fetchBuildings(area, source, controller, epoch) {
    controller.signal.throwIfAborted()
    if (
      cache?.source === source &&
      area.bounds.every((v, i) => (i < 2 ? v >= cache.area.bounds[i] : v <= cache.area.bounds[i]))
    )
      return cache.tiles
    const config = getMap().getStyle().sources[source === 'osm' ? 'composite' : 'city-concordia']
    const tiles = await loadRegionTiles({
      sourceConfig: config,
      source,
      bounds: area.bounds,
      accessToken,
      signal: controller.signal,
      paddingTiles: 1,
      onProgress: (p) => {
        if (epoch === revision) state.progress = p
      },
    })
    if (disposed || controller.signal.aborted || epoch !== revision) throw new DOMException('Cancelled', 'AbortError')
    const preview = createBuildingPreview(tiles.features)
    cache = { source, area, tiles, preview }
    state.loadedArea = markRaw({
      source,
      bounds: [...area.bounds],
      extentM: [...area.extentM],
      count: preview.features.length,
    })
    paint()
    return tiles
  }
  /** Load a 3km working square, fit it on screen, and keep its detail when the camera zoom changes. */
  async function loadBuildings() {
    if (state.loading || disposed) return null
    const map = getMap()
    if (!map || !ready.value) {
      state.error = 'Wait for the map to load.'
      return null
    }
    const controller = new AbortController(),
      epoch = revision,
      source = state.source
    capture = controller
    state.loading = true
    state.progress = 0
    state.error = ''
    try {
      const centre = map.getCenter().wrap().toArray()
      const southwest = makeUnprojector(centre)([-1500, -1500])
      // Construct both dimensions at the SAME anchor: symmetric offsets about another latitude can round beyond the requested size.
      const area = createRegion(southwest, makeUnprojector(southwest)([3000, 3000]))
      fitArea(area)
      await fetchBuildings(area, source, controller, epoch)
      if (disposed || controller.signal.aborted || epoch !== revision) return null
      state.snapshot = null
      onChange?.()
      return state.loadedArea
    } catch (error) {
      controller.abort()
      if (!disposed && epoch === revision && error.name !== 'AbortError') state.error = error.message
      return null
    } finally {
      if (capture === controller) {
        capture = null
        if (!disposed) state.loading = false
      }
    }
  }

  async function captureRegion() {
    if (state.loading || disposed) return null
    if (!state.region && cache?.source === state.source) setSelection(cache.area.polygon)
    const map = getMap(),
      region = state.region,
      source = state.source,
      epoch = revision
    if (!map || !ready.value || !region) {
      state.error = 'Draw and finish a valid polygon first.'
      return null
    }
    const controller = new AbortController()
    capture = controller
    state.loading = true
    state.progress = 0
    state.error = ''
    try {
      // A previous fit can be smaller than the drawn area, especially after changing providers.
      const drawnRegion = createPolygonRegion(region.selection ?? region.polygon)
      let area = drawnRegion,
        input,
        tiles
      for (let attempt = 0; attempt < 4; attempt++) {
        tiles = await fetchBuildings(area, source, controller, epoch)
        if (disposed || controller.signal.aborted || epoch !== revision) return null
        input = selectBuildings(tiles.features, drawnRegion)
        const coverage = tiles.coverageBounds
        const complete = input.bounds.every((v, i) => (i < 2 ? v > coverage[i] + 1e-8 : v < coverage[i] - 1e-8))
        if (complete || !input.buildings.features.length) break
        if (attempt === 3)
          throw new Error('Selected buildings still reach the loaded tile boundary. Choose a smaller group.')
        area = input
      }
      input.source = source
      input.dataZoom = tiles.zoom
      input.tileCount = tiles.tileCount
      input.surroundings = createBuildingPreview(input.surroundings.features)
      input.warnings = input.warnings.filter((w) => !w.startsWith('Loaded map tiles only'))
      input.warnings.push(
        'Detailed tiles downloaded at zoom ' +
          tiles.zoom +
          ' independently of the camera; provider data may still omit buildings.',
      )
      input.warnings.push(
        'Whole buildings touching the drawn polygon are selected. Unselected buildings inside the fitted rectangle are open ground.',
      )
      state.snapshot = markRaw(input)
      state.region = markRaw({
        origin: input.origin,
        bounds: input.bounds,
        extentM: input.extentM,
        polygon: input.polygon,
        selection: input.selection,
      })
      paint()
      fitArea(input)
      onChange?.()
      return input
    } catch (error) {
      controller.abort()
      if (!disposed && epoch === revision && error.name !== 'AbortError') state.error = error.message
      return null
    } finally {
      if (capture === controller) {
        capture = null
        if (!disposed) state.loading = false
      }
    }
  }
  function detachDraw() {
    const map = getMap()
    if (!draw || !map) return
    for (const event of ['draw.create', 'draw.update', 'draw.delete']) map.off(event, readDrawing)
    map.off('draw.modechange', drawMode)
    map.removeControl(draw)
    draw = null
    state.drawing = false
  }
  function beforeStyleChange() {
    capture?.abort()
    detachDraw()
  }
  function restore() {
    paint()
    if (state.region?.selection) ensureDraw()
  }
  function dispose() {
    disposed = true
    revision++
    capture?.abort()
    detachDraw()
  }
  watch(
    () => state.source,
    () => {
      invalidate()
      paint()
      state.error = ''
    },
  )
  onBeforeUnmount(dispose)
  /** Return the full cached preview FeatureCollection (all buildings in the loaded area). */
  function getPreview() {
    return cache?.preview ?? null
  }
  return {
    state,
    startSelection,
    stopSelection,
    clearSelection,
    setSelection,
    captureRegion,
    loadBuildings,
    getPreview,
    restore,
    beforeStyleChange,
    dispose,
  }
}
