import { makeProjector } from '../../preprocessing/stl-converter/geojsonToStl.js'

/**
 * Selected whole WGS84 footprints -> roof layer counts [ny,nx], X east / Y north.
 * Cell centres are (x+.5,y+.5)*4 metres. Polygon rings use even-odd scanlines to preserve holes.
 */
export function buildHeightGrid(region) {
  const [width, height] = region.extentM,
    nx = Math.round(width / 4),
    ny = Math.round(height / 4)
  if (
    nx < 1 ||
    ny < 1 ||
    !Number.isSafeInteger(nx * ny) ||
    Math.abs(nx * 4 - width) > 1e-5 ||
    Math.abs(ny * 4 - height) > 1e-5
  )
    throw new Error('Invalid grid extent; use positive dimensions snapped to 4m cells.')
  const project = makeProjector(region.origin),
    layers = new Float32Array(nx * ny)
  for (const feature of region.buildings.features) {
    const roof = Number(feature.properties.height)
    if (!Number.isFinite(roof) || roof < 0 || roof > 240) throw new Error('Invalid building height (0..240 metres).')
    if (!roof) continue
    const level = Math.max(1, Math.round(roof / 1.5))
    const polygons = feature.geometry.type === 'Polygon' ? [feature.geometry.coordinates] : feature.geometry.coordinates
    for (const polygon of polygons) {
      const rings = polygon.map((r) => r.map(project))
      let low = Infinity,
        high = -Infinity
      for (const ring of rings)
        for (const p of ring) {
          low = Math.min(low, p[1])
          high = Math.max(high, p[1])
        }
      for (let y = Math.max(0, Math.ceil(low / 4 - 0.5)); y < Math.min(ny, Math.ceil(high / 4 - 0.5)); y++) {
        const sy = (y + 0.5) * 4,
          cuts = []
        for (const ring of rings)
          for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
            const a = ring[j],
              b = ring[i]
            if ((a[1] <= sy && b[1] > sy) || (b[1] <= sy && a[1] > sy))
              cuts.push(a[0] + ((sy - a[1]) * (b[0] - a[0])) / (b[1] - a[1]))
          }
        cuts.sort((a, b) => a - b)
        for (let i = 0; i + 1 < cuts.length; i += 2) {
          const start = Math.max(0, Math.ceil(cuts[i] / 4 - 0.5 - 1e-8)),
            end = Math.min(nx, Math.ceil(cuts[i + 1] / 4 - 0.5 - 1e-8))
          for (let x = start; x < end; x++) layers[y * nx + x] = Math.max(layers[y * nx + x], level)
        }
      }
    }
  }
  let built = 0,
    maximum = 0
  for (const value of layers) {
    if (value > 0) built++
    maximum = Math.max(maximum, value)
  }
  return {
    layers,
    nx,
    ny,
    origin: [...region.origin],
    extentM: [...region.extentM],
    spacingM: 4,
    layerSpacingM: 1.5,
    statistics: { builtCells: built, maximumHeightM: maximum * 1.5 },
  }
}
