import { createBuildingPreview } from './buildingPreview.js'

export const BUILDING_DETAIL_ZOOM = 16
const SOURCE = 'flume-retained-buildings',
  SELECTED = 'flume-retained-selected'

/** Keep already downloaded detail when native tiles switch to a coarser zoom; never fetch the whole zoomed-out city. */
export function createBuildingRetention(map, onError) {
  let config = null,
    seed = null,
    data = null,
    uploadedData = null,
    timer = null
  function paint() {
    if (!config) return
    if (!map.getSource(SOURCE)) map.addSource(SOURCE, { type: 'geojson', data, maxzoom: 22, tolerance: 0 })
    else if (data !== uploadedData) map.getSource(SOURCE).setData(data)
    uploadedData = data
    for (const [id, selected] of [
      [SOURCE, false],
      [SELECTED, true],
    ]) {
      const filter = config.filters[selected ? 'selected' : 'surroundings']
      if (!map.getLayer(id))
        map.addLayer({
          id,
          type: 'fill-extrusion',
          source: SOURCE,
          maxzoom: BUILDING_DETAIL_ZOOM,
          filter,
          layout: { visibility: 'visible' },
          paint: {
            'fill-extrusion-color': selected ? '#9aa3ad' : '#8cb8d8',
            'fill-extrusion-height': ['get', 'height'],
            'fill-extrusion-base': ['get', 'min_height'],
            'fill-extrusion-opacity': selected ? 1 : config.surroundingsOpacity,
          },
        })
      else map.setFilter(id, filter)
      map.setPaintProperty(id, 'fill-extrusion-opacity', selected ? 1 : config.surroundingsOpacity)
      map.setLayoutProperty(id, 'visibility', selected || config.showSurroundings ? 'visible' : 'none')
    }
  }
  function collect() {
    if (
      !config ||
      map.getZoom() < BUILDING_DETAIL_ZOOM ||
      !map.getSource(config.sourceId) ||
      !map.isSourceLoaded(config.sourceId)
    )
      return
    try {
      const fresh = map
        .querySourceFeatures(config.sourceId, { sourceLayer: config.sourceLayer })
        .filter((feature) => !feature.tile || feature.tile.z >= (config.dataZoom ?? BUILDING_DETAIL_ZOOM))
      // shortcut: retained detail grows within this selection; add tile eviction for very long exploration sessions.
      data = createBuildingPreview([...data.features, ...fresh])
      paint()
    } catch (error) {
      onError?.(error)
    }
  }
  function schedule(event) {
    if (!config || (event?.sourceId && event.sourceId !== config.sourceId)) return
    clearTimeout(timer)
    timer = setTimeout(collect, 120)
  }
  function update(next) {
    if (seed !== next.collection || config?.sourceId !== next.sourceId || config?.sourceLayer !== next.sourceLayer) {
      data = createBuildingPreview(next.collection?.features ?? [])
      seed = next.collection
    }
    config = next
    paint()
    schedule()
  }
  function clear() {
    clearTimeout(timer)
    config = null
    seed = null
    data = null
    uploadedData = null
    for (const id of [SELECTED, SOURCE]) if (map.getLayer(id)) map.removeLayer(id)
    if (map.getSource(SOURCE)) map.removeSource(SOURCE)
  }
  map.on('sourcedata', schedule)
  map.on('moveend', schedule)
  return {
    update,
    clear,
    dispose() {
      map.off('sourcedata', schedule)
      map.off('moveend', schedule)
      clear()
    },
  }
}
