import { markRaw, onBeforeUnmount, reactive } from 'vue'
import { Context } from './context.js'
import { Predictor } from './predict.js'
import { preparePrediction, validateModel } from './modelData.js'

/** Owns ONE GPU session. Lazy model loading; source/grid changes rebuild MDDF, direction changes reuse it. */
export function useFlumePrediction() {
  const state = reactive({ busy: false, progress: 0, stage: 'Ready', error: '', prediction: null, downloading: false })
  let context = null,
    predictor = null,
    metadata = null,
    colors = null,
    gridInGpu = null,
    disposed = false,
    revision = 0
  const abort = new AbortController()
  function release() {
    try {
      predictor?.destroy()
    } finally {
      context?.device.destroy()
      predictor = null
      context = null
      gridInGpu = null
    }
  }
  async function initialize() {
    if (predictor) return
    state.stage = 'Loading model'
    const base = import.meta.env.BASE_URL + 'flume/'
    const [meta, blob, scales] = await Promise.all(
      ['model/metadata.json', 'model/weights.bin', 'colorbar.json'].map(async (name) => {
        const response = await fetch(base + name, { signal: abort.signal })
        if (!response.ok) throw new Error('Could not load ' + name + ' (HTTP ' + response.status + ').')
        return name.endsWith('.bin') ? response.arrayBuffer() : response.json()
      }),
    )
    validateModel(meta, blob.byteLength)
    abort.signal.throwIfAborted()
    context = await Context.create()
    abort.signal.throwIfAborted()
    context.device.addEventListener('uncapturederror', (event) => {
      state.error = 'WebGPU: ' + event.error.message.split('\n')[0]
    })
    context.device.lost.then((info) => {
      if (!disposed && info.reason !== 'destroyed') {
        state.error = 'GPU device lost. Run again to initialize a new session.'
        state.prediction = null
        predictor = null
        context = null
        gridInGpu = null
      }
    })
    metadata = meta
    colors = scales
    predictor = new Predictor(context, metadata, blob, { batchSize: 4 })
  }
  async function run(grid, settings) {
    if (disposed || state.busy || state.downloading) return null
    state.busy = true
    state.error = ''
    state.progress = 0
    // Keep the previous field on the map until this revision lands.
    const inputRevision = ++revision
    try {
      await initialize()
      if (disposed || inputRevision !== revision) return null
      if (grid !== gridInGpu) {
        predictor.setCity(grid.layers, grid.ny, grid.nx)
        gridInGpu = grid
      }
      state.stage = 'Preparing geometry · MDDF'
      await predictor.setHeight(settings.layerIndex, {
        signal: abort.signal,
        onProgress: (v) => {
          if (!disposed && inputRevision === revision) state.progress = v * 0.25
        },
      })
      if (disposed || inputRevision !== revision) return null
      state.stage = 'Predicting wind · FNO'
      const result = await predictor.predict(settings.thetaRad, {
        signal: abort.signal,
        onProgress: (v) => {
          if (!disposed && inputRevision === revision) state.progress = 0.25 + v * 0.75
        },
      })
      abort.signal.throwIfAborted()
      if (disposed || inputRevision !== revision) return null
      if (state.error) throw new Error(state.error)
      preparePrediction(result)
      const prediction = {
        ...result,
        grid,
        settings: { ...settings },
        referenceSpeed: metadata.wind.reference_speed_m_s,
        modelLabel: metadata.label,
        colorbar: colors,
        inputRevision,
      }
      state.prediction = markRaw(prediction)
      state.progress = 1
      state.stage = 'Prediction ready'
      return prediction
    } catch (error) {
      if (!disposed && inputRevision === revision) {
        state.error = error.message
        state.stage = 'Prediction failed'
        state.prediction = null
      }
      release()
      return null
    } finally {
      if (!disposed) state.busy = false
      else release()
    }
  }
  /** Read unnormalised Fourier coefficients [expandedNy,expandedNx,28] only on explicit download. */
  async function readMddf() {
    if (!predictor || !state.prediction || state.busy || state.downloading)
      throw new Error('Run a valid prediction before downloading MDDF.')
    state.downloading = true
    try {
      const field = predictor.city.field
      const values = await context.readFloat32(field.fieldBuffer, field.gy * field.gx * 28)
      if (disposed) throw new Error('The page was closed.')
      return { values, ny: field.gy, nx: field.gx, margin: field.margin, layerIndex: predictor.city.layerIndex }
    } finally {
      state.downloading = false
      if (disposed) release()
    }
  }
  function invalidate() {
    revision++
    state.prediction = null
    state.error = ''
    state.progress = 0
    state.stage = 'Ready'
  }
  function dispose() {
    disposed = true
    revision++
    abort.abort()
    if (!state.busy && !state.downloading) release()
  }
  onBeforeUnmount(dispose)
  return { state, run, readMddf, invalidate, dispose }
}
