import { mergeBuildingParts, buildingId } from './regionData.js'

export const PREVIEW_LAYER_ID = 'flume-detailed-buildings'

/** Display data keeps real roof/base metres. The model's 240m limit applies only when a simulation is prepared. */
export function createBuildingPreview(features) {
  const buildings = []
  for (const feature of mergeBuildingParts(features)) {
    const height = Number(feature.properties?.height)
    if (!Number.isFinite(height) || height <= 0) continue
    const base = Math.min(height, Math.max(0, Number(feature.properties?.min_height) || 0))
    buildings.push({
      ...feature,
      properties: { ...feature.properties, height, min_height: base },
      geometry: feature.geometry,
    })
  }
  return { type: 'FeatureCollection', features: buildings }
}

/** A detailed GeoJSON overlay is independent of the native tileset's display minzoom. Restore after style changes. */
export function showBuildingPreview(map, collection) {
  if (!collection?.features?.length) {
    if (map.getLayer(PREVIEW_LAYER_ID)) map.removeLayer(PREVIEW_LAYER_ID)
    if (map.getSource(PREVIEW_LAYER_ID)) map.removeSource(PREVIEW_LAYER_ID)
    return
  }
  const data = collection
  if (map.getSource(PREVIEW_LAYER_ID)) map.getSource(PREVIEW_LAYER_ID).setData(data)
  else map.addSource(PREVIEW_LAYER_ID, { type: 'geojson', data, maxzoom: 22, tolerance: 0 })
  if (!map.getLayer(PREVIEW_LAYER_ID))
    map.addLayer({
      id: PREVIEW_LAYER_ID,
      type: 'fill-extrusion',
      source: PREVIEW_LAYER_ID,
      minzoom: 0,
      paint: {
        'fill-extrusion-color': '#8cb8d8',
        'fill-extrusion-height': ['get', 'height'],
        'fill-extrusion-base': ['get', 'min_height'],
        'fill-extrusion-opacity': 1,
      },
    })
}

/** Complementary filters on ONE native source: each provider building renders in exactly one group. */
export function buildingFilters(features, baseFilter = null) {
  const ids = features.map(buildingId)
  if (ids.some((id) => id == null))
    throw new Error('Selected buildings need a stable provider ID (nd, osm_id or feature ID) for map styling.')
  const identity = [
    'to-string',
    ['coalesce', ['get', 'nd'], ['get', 'osm_id'], ['id'], ['get', 'id'], ['get', 'auto_id'], ''],
  ]
  const match = ['in', identity, ['literal', Array.from(new Set(ids))]]
  return {
    selected: baseFilter ? ['all', baseFilter, match] : match,
    surroundings: baseFilter ? ['all', baseFilter, ['!', match]] : ['!', match],
  }
}
