import { scaledChannels } from './field.js'

function floatFile(name, values, shape, channels, unit) {
  if (shape.reduce((a, b) => a * b, 1) !== values.length) throw new Error('Invalid ' + name + ' shape.')
  const bytes = new Uint8Array(values.length * 4),
    view = new DataView(bytes.buffer)
  for (let i = 0; i < values.length; i++) {
    if (!Number.isFinite(values[i])) throw new Error('Cannot export non-finite ' + name)
    view.setFloat32(i * 4, values[i], true)
  }
  return { name, content: bytes, description: { dtype: 'float32', shape, channels, unit } }
}
function manifest(input, p, files, mddf) {
  const meta = {
    schemaVersion: 1,
    endianness: 'little',
    order: 'row-major',
    origin: input.origin,
    source: input.source,
    bounds: input.bounds,
    selection: input.selection?.geometry ?? input.polygon?.geometry,
    computationalDomain: input.polygon?.geometry,
    dataZoom: input.dataZoom,
    tileCount: input.tileCount,
    warnings: input.warnings,
    projection: 'local equirectangular metres at origin',
    axes: { x: 'east', y: 'north', z: 'up' },
    grid: { nx: p.grid.nx, ny: p.grid.ny, spacingM: 4, layerSpacingM: 1.5, extentM: p.grid.extentM },
    windGrid: {
      width: p.width,
      height: p.height,
      originX: p.originX,
      originY: p.originY,
      thetaRad: p.theta,
      cellPosition: 'Rotate (originX+x,originY+y) about ((nx-1)/2,(ny-1)/2), then add 0.5 and multiply by 4 metres.',
    },
    settings: p.settings,
    referenceSpeedMps: p.referenceSpeed,
    model: p.modelLabel,
    velocityFrame:
      'u along wind, v across wind, w upwards; east=u*cos(theta)-v*sin(theta), north=u*sin(theta)+v*cos(theta)',
    ...(mddf
      ? {
          mddf: {
            nx: mddf.nx,
            ny: mddf.ny,
            margin: mddf.margin,
            layerIndex: mddf.layerIndex,
            representation:
              'unnormalized angular Fourier coefficients; not raw rays or normalized 24-channel FNO input',
          },
        }
      : {}),
    files: Object.fromEntries(files.map((f) => [f.name, f.description])),
  }
  return [
    { name: 'metadata.json', content: JSON.stringify(meta, null, 2) },
    ...files.map(({ name, content }) => ({ name, content })),
  ]
}
function mddfFiles(p, m) {
  const signals = ['upper_distance', 'upper_relative_height', 'lower_distance', 'lower_relative_height']
  const channels = signals.flatMap((signal) =>
    ['dc', 're1', 're2', 're3', 'im1', 'im2', 'im3'].map((mode) => signal + '_' + mode),
  )
  return [
    floatFile('mddf.f32.bin', m.values, [m.ny, m.nx, 28], channels, 'm'),
    floatFile('height_layers.f32.bin', p.grid.layers, [p.grid.ny, p.grid.nx], ['roof_layer_count'], '1.5 m per layer'),
  ]
}
function windFiles(p, all = false) {
  const values = scaledChannels(p),
    cells = p.width * p.height,
    velocity = new Float32Array(cells * 3),
    temperature = new Float32Array(cells),
    tke = new Float32Array(cells),
    speed = new Float32Array(cells)
  for (let i = 0; i < cells; i++) {
    const b = i * 5
    velocity.set([values[b], values[b + 2], values[b + 1]], i * 3)
    temperature[i] = values[b + 3]
    tke[i] = values[b + 4]
    speed[i] = Math.hypot(values[b], values[b + 1], values[b + 2])
  }
  return [
    floatFile('velocity.f32.bin', velocity, [p.height, p.width, 3], ['u', 'v', 'w'], 'm/s'),
    {
      name: 'mask.u8.bin',
      content: Uint8Array.from(p.solid),
      description: {
        dtype: 'uint8',
        shape: [p.height, p.width],
        values: { 0: 'air', 1: 'building', 2: 'outside/uncovered/invalid' },
      },
    },
    ...(all
      ? [
          floatFile('temperature.f32.bin', temperature, [p.height, p.width], ['T'], 'degC'),
          floatFile('tke.f32.bin', tke, [p.height, p.width], ['TKE'], 'm2/s2'),
          floatFile('speed.f32.bin', speed, [p.height, p.width], ['speed'], 'm/s'),
        ]
      : []),
  ]
}
/** Numeric inputs -> named files for the existing zipFiles({name,content}) helper. Exactly one root manifest per ZIP. */
export function buildMddfFiles(input, mddf, p) {
  return manifest(input, p, mddfFiles(p, mddf), mddf)
}
export function buildWindFiles(input, p) {
  return manifest(input, p, windFiles(p))
}
export function buildAllFiles(input, mddf, p) {
  const files = [
    ...mddfFiles(p, mddf),
    ...windFiles(p, true),
    {
      name: 'buildings.geojson',
      content: JSON.stringify(input.buildings),
      description: { format: 'GeoJSON', crs: 'WGS84' },
    },
  ]
  return manifest(input, p, files, mddf)
}
