<!-- Nested settings belong to the page controller; this HUD edits that shared draft, not the prop reference. -->
<script setup>
/* eslint vue/no-mutating-props: ['error', { shallowOnly: true }] */
defineProps({ region: { type: Object, required: true }, ready: Boolean, locked: Boolean })
defineEmits(['continue'])
</script>
<template>
  <!-- Compact region controls: source + actions in short rows, no tall prose blocks. -->
  <div class="flume-compact">
    <VaSelect
      v-model="region.state.source"
      label="Buildings"
      aria-label="Building source"
      size="small"
      :options="[
        { text: 'Concordia 3D', value: 'concordia' },
        { text: 'OSM 3D', value: 'osm' },
      ]"
      text-by="text"
      value-by="value"
      :disabled="region.state.loading || locked"
    />
    <VaButton
      block
      size="small"
      preset="secondary"
      icon="mso-location_city"
      :disabled="!ready || region.state.loading || locked"
      :loading="region.state.loading"
      @click="region.loadBuildings"
      >Show detailed buildings</VaButton
    >
    <p v-if="region.state.loadedArea" class="flume-meta" role="status">
      Loaded detailed buildings: {{ region.state.loadedArea.count }} parts ·
      {{ (region.state.loadedArea.extentM[0] / 1000).toFixed(1) }} ×
      {{ (region.state.loadedArea.extentM[1] / 1000).toFixed(1) }} km. Detail stays when you zoom.
    </p>
    <p v-else class="flume-muted">Quick-load a 3 × 3 km area around the map centre, or draw a larger area directly.</p>

    <div class="flume-actions">
      <VaButton
        size="small"
        preset="secondary"
        icon="mso-crop_free"
        :disabled="!ready || region.state.loading || locked"
        aria-label="Select region"
        @click="region.startSelection"
        >Draw area</VaButton
      >
      <VaButton
        size="small"
        :disabled="!ready || (!region.state.region && !region.state.loadedArea) || locked"
        :loading="region.state.loading"
        :aria-label="region.state.region ? 'Use selected region' : 'Use full loaded area'"
        @click="$emit('continue')"
        >{{ region.state.region ? 'Use region' : 'Use full area' }}</VaButton
      >
    </div>
    <p v-if="region.state.drawing" role="status" class="flume-muted">
      Draw around buildings; touching the edge selects the whole building. Click the first point to finish. Esc cancels.
    </p>
    <p v-else-if="region.state.region" class="flume-meta">
      {{ region.state.region.extentM[0] }} × {{ region.state.region.extentM[1] }} m · 4 m cells · fitted domain
      <button
        type="button"
        class="flume-link"
        :disabled="region.state.loading || locked"
        @click="region.clearSelection"
      >
        Clear
      </button>
    </p>
    <VaProgressBar
      v-if="region.state.loading"
      :model-value="region.state.progress * 100"
      aria-label="Loading building data"
    />
    <VaAlert v-if="region.state.error" color="danger">{{ region.state.error }}</VaAlert>
  </div>
</template>
