import * as THREE from 'three'
import mapboxgl from 'mapbox-gl'
import { ParticleFlow } from './particles.js'
import { VARIABLES, fieldTexels, paletteBytes, fitRange, flowField, localCellPoint, scaleFor } from './field.js'

const VERTEX = `
#include <clipping_planes_pars_vertex>
varying vec2 vUv;
void main(){vUv=uv; vec4 mvPosition=modelViewMatrix*vec4(position,1.0);gl_Position=projectionMatrix*mvPosition;
#include <clipping_planes_vertex>
}`
const FRAGMENT = `
#include <clipping_planes_pars_fragment>
uniform sampler2D field;uniform sampler2D palette;uniform vec2 range;varying vec2 vUv;
void main(){
#include <clipping_planes_fragment>
vec4 texel=texture2D(field,vUv);if(texel.g<0.5)discard;
float t=clamp((texel.r-range.x)/max(range.y-range.x,1e-6),0.0,1.0);
gl_FragColor=vec4(texture2D(palette,vec2(t,0.5)).rgb,0.88);
#include <colorspace_fragment>
}`

/** A single horizontal FLUME slice and particle trails in Mapbox's shared WebGL depth buffer. Local axes east,north,up. */
export function createFlumeMapLayer(prediction, settings, onRange) {
  let map,
    renderer,
    scene,
    camera,
    plane,
    particles,
    texture,
    palette,
    material,
    last = 0
  const transform = new THREE.Matrix4(),
    projection = new THREE.Matrix4()
  const origin = mapboxgl.MercatorCoordinate.fromLngLat(prediction.grid.origin)
  const unit = origin.meterInMercatorCoordinateUnits()
  const [east, north] = localCellPoint(prediction, prediction.width / 2 - 0.5, prediction.height / 2 - 0.5)
  const clip = [
    new THREE.Plane(new THREE.Vector3(1, 0, 0), 0),
    new THREE.Plane(new THREE.Vector3(-1, 0, 0), prediction.grid.nx * 4),
    new THREE.Plane(new THREE.Vector3(0, 1, 0), 0),
    new THREE.Plane(new THREE.Vector3(0, -1, 0), prediction.grid.ny * 4),
  ]
  function configure() {
    if (!renderer) return
    texture?.dispose()
    palette?.dispose()
    const variable = VARIABLES.find((v) => v.id === settings.variable) ?? VARIABLES[0]
    const texels = fieldTexels(prediction, variable.id)
    texture = new THREE.DataTexture(texels, prediction.width, prediction.height, THREE.RGBAFormat, THREE.HalfFloatType)
    texture.minFilter = texture.magFilter = THREE.LinearFilter
    texture.needsUpdate = true
    palette = new THREE.DataTexture(paletteBytes(variable.ramp), 256, 1, THREE.RGBAFormat)
    palette.colorSpace = THREE.SRGBColorSpace
    palette.minFilter = palette.magFilter = THREE.LinearFilter
    palette.needsUpdate = true
    // Match original FLUME: reference-valued texels, with speed applied only to the colour limits.
    const factor = Number(settings.speedMps) / prediction.referenceSpeed
    const power = variable.id === 'T' ? 1 : variable.id === 'tke' ? factor * factor : factor
    const range =
      fitRange(prediction, variable.id, '99.9')?.map((limit) => limit * power) ??
      scaleFor(
        prediction.colorbar,
        variable.id,
        prediction.settings.layerIndex,
        '99.9',
        Number(settings.speedMps) / prediction.referenceSpeed,
      )
    material.uniforms.field.value = texture
    material.uniforms.palette.value = palette
    material.uniforms.range.value.set(...range)
    plane.visible = settings.particles !== 'tinted'
    particles.setMode(settings.particles === 'tinted' ? 'tinted' : 'white')
    particles.enabled = settings.particles !== 'off'
    particles.setField(flowField(prediction, variable.id), 4)
    particles.setTinting(
      settings.particles === 'tinted' ? paletteBytes(variable.ramp) : null,
      settings.particles === 'tinted' ? range : null,
    )
    particles.mesh.visible = particles.enabled
    onRange?.({ low: range[0], high: range[1], ...variable })
    map.triggerRepaint()
  }
  return {
    id: 'flume-field',
    type: 'custom',
    renderingMode: '3d',
    configure,
    onAdd(target, gl) {
      map = target
      scene = new THREE.Scene()
      camera = new THREE.Camera()
      renderer = new THREE.WebGLRenderer({ canvas: map.getCanvas(), context: gl, antialias: true })
      renderer.autoClear = false
      renderer.localClippingEnabled = true
      material = new THREE.ShaderMaterial({
        vertexShader: VERTEX,
        fragmentShader: FRAGMENT,
        uniforms: { field: { value: null }, palette: { value: null }, range: { value: new THREE.Vector2(0, 1) } },
        transparent: true,
        depthWrite: false,
        side: THREE.DoubleSide,
        clipping: true,
        clippingPlanes: clip,
      })
      plane = new THREE.Mesh(new THREE.PlaneGeometry(prediction.width * 4, prediction.height * 4), material)
      plane.position.set(east, north, prediction.settings.heightM)
      plane.rotation.z = prediction.theta
      plane.frustumCulled = false
      scene.add(plane)
      particles = new ParticleFlow(renderer)
      particles.setPlane(prediction.width * 4, prediction.height * 4)
      particles.mesh.geometry.dispose()
      particles.mesh.geometry = plane.geometry.clone()
      particles.mesh.position.copy(plane.position)
      particles.mesh.rotation.copy(plane.rotation)
      particles.material.clippingPlanes = clip
      particles.mesh.renderOrder = 3
      particles.mesh.frustumCulled = false
      scene.add(particles.mesh)
      configure()
    },
    render(gl, matrix) {
      const now = performance.now(),
        dt = Math.min(last ? (now - last) / 1000 : 0, 0.05)
      last = now
      transform.makeTranslation(origin.x, origin.y, origin.z).scale(new THREE.Vector3(unit, -unit, unit))
      camera.projectionMatrix.copy(projection.fromArray(matrix)).multiply(transform)
      camera.projectionMatrixInverse.copy(camera.projectionMatrix).invert()
      renderer.resetState()
      renderer.setViewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight)
      particles.setResolution(gl.drawingBufferWidth, gl.drawingBufferHeight)
      if (particles.enabled && !settings.paused)
        particles.step(dt * (Number(settings.speedMps) / prediction.referenceSpeed), camera, plane)
      renderer.resetState()
      renderer.setViewport(0, 0, gl.drawingBufferWidth, gl.drawingBufferHeight)
      renderer.render(scene, camera)
      if (particles.enabled && !settings.paused) map.triggerRepaint()
    },
    onRemove() {
      texture?.dispose()
      palette?.dispose()
      plane?.geometry.dispose()
      material?.dispose()
      particles?.dispose()
      renderer?.dispose()
      map = null
      renderer = null
    },
  }
}
