<script setup>
defineProps({
  grid: { type: Object, default: null },
  prediction: { type: Object, default: null },
  downloading: Boolean,
  locked: Boolean,
  predicting: Boolean,
  error: { type: String, default: '' },
})
defineEmits(['download'])
</script>

<template>
  <!-- The grid model is available before FNO; numerical exports need a prediction from the current region. -->
  <div class="space-y-2">
    <p v-if="!grid" class="text-xs text-secondary">Choose a simulation area before downloading its model.</p>
    <template v-else>
      <div class="grid grid-cols-2 gap-2">
        <VaButton
          v-for="item in [
            { id: 'model', text: 'STL model', label: 'Download STL model' },
            { id: 'mddf', text: 'MDDF', label: 'Download MDDF' },
            { id: 'all', text: 'All', label: 'Download all results' },
          ]"
          :key="item.id"
          size="small"
          preset="secondary"
          icon="mso-download"
          :aria-label="item.label"
          :disabled="downloading || locked || (item.id !== 'model' && (predicting || !prediction))"
          @click="$emit('download', item.id)"
        >
          {{ item.text }}
        </VaButton>
      </div>
      <VaProgressBar v-if="downloading" indeterminate aria-label="Preparing download" />
      <VaAlert v-if="error" color="danger">{{ error }}</VaAlert>
    </template>
  </div>
</template>
