import { computed, markRaw, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import mapboxgl from 'mapbox-gl'
import { useMapControls } from '../city/controls/useMapControls.js'
import { addBuildingLayers, buildingLayers, setBuildingVisibility } from '../city/layer/buildingLayers.js'
import { showBuildingPreview, buildingFilters } from './selection/buildingPreview.js'
import { createBuildingRetention, BUILDING_DETAIL_ZOOM } from './selection/buildingRetention.js'
import { useFlumeRegion } from './selection/useFlumeRegion.js'
import { buildHeightGrid } from './selection/heightGrid.js'
import { normalizeWindSettings } from './wind/windSettings.js'
import { useFlumePrediction } from './compute/useFlumePrediction.js'
import { createFlumeMapLayer } from './result/flumeMapLayer.js'
import { buildMddfFiles, buildWindFiles, buildAllFiles } from './result/flumeDownloads.js'
import { buildModelFiles } from './result/mddfModelStl.js'
import { zipFiles } from '../preprocessing/shared/archive.js'
import { downloadFile } from '../preprocessing/shared/download.js'

/** Độ mờ của các toà nhà xung quanh khi hiển thị kết quả (giảm xuống để làm nổi bật khối nhà được chọn). */
export const SURROUNDINGS_OPACITY = 0.35

/** Page owner: ONE map and explicit step transitions. Feature modules own their logic; Vue only renders these states. */
export function useFlumeCity() {
  const mapElement = ref(null),
    ready = ref(false),
    initialized = ref(false)
  const state = reactive({
    step: 0,
    error: '',
    grid: null,
    settings: null,
    legend: null,
    downloading: false,
    downloadError: '',
  })
  const draft = reactive({ heightM: 10, directionDeg: 0, speedMps: 6 })
  const display = reactive({
    variable: 'speed',
    speedMps: 6,
    particles: 'white',
    paused: false,
    showSurroundings: true,
  })
  let map,
    observer,
    fieldLayer,
    retention,
    disposed = false,
    runTimer = null,
    pendingRun = false
  const originalBuildingStyles = new Map()
  const getMap = () => map,
    accessToken = import.meta.env.VITE_MAPBOX_TOKEN?.trim()
  const controls = useMapControls({ getMap, accessToken }),
    runner = useFlumePrediction()
  function invalidate() {
    clearTimeout(runTimer)
    runTimer = null
    pendingRun = false
    state.grid = null
    state.settings = null
    state.legend = null
    state.error = ''
    state.downloadError = ''
    state.step = 0
    runner.invalidate()
    syncScene()
  }
  const region = useFlumeRegion({ getMap, ready, onChange: invalidate, accessToken })
  // Downloads lock everything; prediction busy still allows wind edits (queued auto-rerun).
  const locked = computed(() => runner.state.downloading || state.downloading || region.state.loading)
  const regionLocked = computed(() => locked.value || runner.state.busy)
  function buildingVisibility() {
    return {
      'city-concordia-2d': false,
      'city-concordia-3d': region.state.source === 'concordia',
      'city-osm-3d': region.state.source === 'osm',
    }
  }
  function restoreBuildingStyles() {
    for (const [id, saved] of originalBuildingStyles)
      if (map?.getLayer(id)) {
        map.setLayoutProperty(id, 'visibility', saved.visibility)
        map.setPaintProperty(id, saved.property, saved.opacity)
        map.setFilter(id, saved.filter)
        map.setLayerZoomRange(id, saved.minzoom, saved.maxzoom)
        if (saved.color !== undefined) map.setPaintProperty(id, 'fill-extrusion-color', saved.color)
      }
    originalBuildingStyles.clear()
  }
  /** Render the frozen input in Results; never query visible geometry while displaying or exporting a prediction. */
  function syncScene() {
    if (!map || !ready.value) return
    const p = runner.state.prediction,
      show = state.step === 3 && p
    if (!show && map.getLayer('flume-field')) {
      map.removeLayer('flume-field')
      fieldLayer = null
    }
    if (!show && map.getLayer('flume-buildings')) map.removeLayer('flume-buildings')
    restoreBuildingStyles()
    setBuildingVisibility(map, buildingVisibility())
    // Region reset drops the cache, so this removes preview layers instead of reviving the old scene.
    if (!show) {
      retention?.clear()
      const fullPreview = region.getPreview()
      showBuildingPreview(map, fullPreview)
      return
    }
    // Styling stays on the native tileset, so buildings outside the simulation keep streaming while panning.
    showBuildingPreview(map, null)
    const entry = buildingLayers.find(
      (e) => e.id === (region.state.source === 'osm' ? 'city-osm-3d' : 'city-concordia-3d'),
    )
    const filters = buildingFilters(region.state.snapshot.buildings.features, map.getFilter(entry.id))
    for (const layer of map.getStyle().layers) {
      // Selected buildings keep opacity 1 in every field/particle mode, including when surroundings are hidden.
      if (layer.id.startsWith('flume-')) continue
      const property =
        layer.type === 'fill-extrusion'
          ? 'fill-extrusion-opacity'
          : layer['source-layer'] === 'building' && ['fill', 'line'].includes(layer.type)
            ? layer.type + '-opacity'
            : null
      if (!property) continue
      originalBuildingStyles.set(layer.id, {
        visibility: map.getLayoutProperty(layer.id, 'visibility') ?? 'visible',
        property,
        opacity: map.getPaintProperty(layer.id, property) ?? 1,
        filter: map.getFilter(layer.id) ?? null,
        minzoom: layer.minzoom ?? 0,
        maxzoom: layer.maxzoom ?? 24,
        color:
          layer.type === 'fill-extrusion'
            ? (map.getPaintProperty(layer.id, 'fill-extrusion-color') ?? null)
            : undefined,
      })
      map.setPaintProperty(layer.id, property, SURROUNDINGS_OPACITY)
      if (layer.type === 'fill-extrusion') map.setPaintProperty(layer.id, 'fill-extrusion-color', '#8cb8d8')
      if (!display.showSurroundings) map.setLayoutProperty(layer.id, 'visibility', 'none')
    }
    // Exact inverse filters share one provider source: there are no copied overlapping building surfaces.
    map.setFilter(entry.id, filters.surroundings)
    map.setLayerZoomRange(entry.id, BUILDING_DETAIL_ZOOM, entry.layer.maxzoom ?? 24)
    if (!map.getLayer('flume-buildings'))
      map.addLayer({
        ...entry.layer,
        id: 'flume-buildings',
        minzoom: BUILDING_DETAIL_ZOOM,
        layout: { visibility: 'visible' },
        filter: filters.selected,
        paint: { ...entry.layer.paint, 'fill-extrusion-color': '#9aa3ad', 'fill-extrusion-opacity': 1 },
      })
    else map.setFilter('flume-buildings', filters.selected)
    retention?.update({
      sourceId: entry.layer.source,
      sourceLayer: entry.layer['source-layer'],
      collection: region.getPreview(),
      dataZoom: region.state.snapshot.dataZoom,
      filters,
      surroundingsOpacity: SURROUNDINGS_OPACITY,
      showSurroundings: display.showSurroundings,
    })
    if (!map.getLayer('flume-field')) {
      fieldLayer = createFlumeMapLayer(p, display, (value) => {
        if (!disposed) state.legend = value
      })
      map.addLayer(fieldLayer)
    }
    map.triggerRepaint()
  }
  async function acceptRegion() {
    if (regionLocked.value) return
    const input = await region.captureRegion()
    if (!input || disposed) return
    try {
      buildingFilters(input.buildings.features)
      state.grid = markRaw(buildHeightGrid(input))
      state.step = 1
      state.error = ''
      scheduleRun()
    } catch (error) {
      state.error = error.message
    }
  }
  function acceptWind() {
    try {
      state.settings = normalizeWindSettings(draft)
      display.speedMps = state.settings.speedMps
      state.error = ''
      if (state.step < 2) state.step = 2
      return true
    } catch (error) {
      state.error = error.message
      return false
    }
  }
  /** Height/direction recompute FNO; trailing debounce while the dial/slider move. */
  function scheduleRun() {
    if (!state.grid || disposed) return
    clearTimeout(runTimer)
    runTimer = setTimeout(() => {
      runTimer = null
      run()
    }, 320)
  }
  async function run() {
    clearTimeout(runTimer)
    runTimer = null
    if (disposed || !state.grid || locked.value) return
    if (runner.state.busy) {
      pendingRun = true
      return
    }
    if (!acceptWind()) return
    const p = await runner.run(state.grid, state.settings)
    if (p && !disposed) state.step = 3
    if (pendingRun && !disposed) {
      pendingRun = false
      await run()
    }
  }
  async function download(kind) {
    if (locked.value || !state.grid) return
    if (kind !== 'model' && (runner.state.busy || !runner.state.prediction)) return
    state.downloading = true
    state.downloadError = ''
    try {
      const input = region.state.snapshot
      let files
      if (kind === 'model') files = await buildModelFiles(input, state.grid, { shouldCancel: () => disposed })
      else {
        const p = {
          ...runner.state.prediction,
          settings: { ...runner.state.prediction.settings, speedMps: Number(display.speedMps) },
        }
        if (!Number.isFinite(p.settings.speedMps) || p.settings.speedMps < 0.5 || p.settings.speedMps > 20)
          throw new Error('Use a wind speed between 0.5 and 20 m/s.')
        const mddf = kind === 'wind' ? null : await runner.readMddf()
        files =
          kind === 'all'
            ? buildAllFiles(input, mddf, p)
            : kind === 'mddf'
              ? buildMddfFiles(input, mddf, p)
              : buildWindFiles(input, p)
      }
      const bytes = await zipFiles(files)
      if (!disposed) downloadFile(bytes, 'flume-' + kind + '.zip', 'application/zip')
    } catch (error) {
      if (!disposed) state.downloadError = error.message
    } finally {
      if (!disposed) state.downloading = false
    }
  }
  watch(() => state.step, syncScene)
  watch(
    () => runner.state.prediction,
    () => {
      if (!map || !ready.value) return
      if (map.getLayer('flume-field')) {
        map.removeLayer('flume-field')
        fieldLayer = null
      }
      syncScene()
    },
  )
  // Like original FLUME: height + direction recompute; speed is display-only.
  watch(
    () => [draft.heightM, draft.directionDeg],
    () => {
      if (state.grid) scheduleRun()
    },
  )
  watch(
    () => draft.speedMps,
    (value) => {
      const speed = Number(value)
      if (!Number.isFinite(speed) || speed < 0.5 || speed > 20) return
      display.speedMps = speed
      if (state.settings) state.settings.speedMps = speed
    },
  )
  watch(
    () => region.state.source,
    () => {
      if (map && ready.value) setBuildingVisibility(map, buildingVisibility())
    },
  )
  watch(() => display.showSurroundings, syncScene)
  watch(
    () => display.paused,
    () => map?.triggerRepaint(),
  )
  watch(
    () => [display.variable, display.particles, display.speedMps],
    () => {
      const speed = Number(display.speedMps)
      if (Number.isFinite(speed) && speed >= 0.5 && speed <= 20) {
        state.downloadError = ''
        fieldLayer?.configure()
      } else state.downloadError = 'Use a wind speed between 0.5 and 20 m/s.'
    },
  )
  watch(controls.mapStyle, (style) => {
    if (!map) return
    region.beforeStyleChange()
    ready.value = false
    fieldLayer = null
    originalBuildingStyles.clear()
    map.setStyle(style, { diff: false })
  })
  onMounted(() => {
    if (!accessToken?.startsWith('pk.')) {
      state.error = 'Set VITE_MAPBOX_TOKEN to a public Mapbox token and restart dev.'
      return
    }
    try {
      map = new mapboxgl.Map({
        container: mapElement.value,
        accessToken,
        style: controls.mapStyle.value,
        center: [-73.5673, 45.5017],
        zoom: 14,
        pitch: 0,
        antialias: true,
        attributionControl: false,
      })
      retention = createBuildingRetention(map, (error) => {
        if (!disposed) state.error = error.message
      })
      initialized.value = true
      map.on('style.load', () => {
        if (disposed) return
        try {
          addBuildingLayers(map, buildingVisibility())
          ready.value = true
          region.restore()
          syncScene()
        } catch (error) {
          state.error = error.message
        }
      })
      map.on('error', (event) => {
        if (!disposed)
          state.error =
            'Map data unavailable' +
            (event.sourceId ? ' (' + event.sourceId + ')' : '') +
            '. Check token, allowed domains and connection.'
      })
      controls.attach()
      observer = new ResizeObserver(() => map?.resize())
      observer.observe(mapElement.value)
    } catch (error) {
      state.error = error.message
    }
  })
  onBeforeUnmount(() => {
    disposed = true
    clearTimeout(runTimer)
    region.dispose()
    runner.dispose()
    retention?.dispose()
    observer?.disconnect()
    map?.remove()
    map = null
  })
  return {
    mapElement,
    ready,
    initialized,
    state,
    draft,
    display,
    controls,
    region,
    runner,
    locked,
    regionLocked,
    acceptRegion,
    acceptWind,
    run,
    scheduleRun,
    download,
  }
}
