import { PbfReader } from 'pbf'
import { VectorTile } from '@mapbox/vector-tile'

/** WGS84 bounds -> XYZ tiles at a fixed data zoom, independent of the camera. */
export function tileCoordinates(bounds, z, padding = 0) {
  const n = 2 ** z,
    tx = (lon) => ((lon + 180) / 360) * n
  const ty = (lat) => {
    const r = (Math.max(-85.051129, Math.min(85.051129, lat)) * Math.PI) / 180
    return ((1 - Math.asinh(Math.tan(r)) / Math.PI) / 2) * n
  }
  const x0 = Math.max(0, Math.floor(tx(bounds[0])) - padding),
    x1 = Math.min(n - 1, Math.ceil(tx(bounds[2]) - 1e-9) - 1 + padding)
  const y0 = Math.max(0, Math.floor(ty(bounds[3])) - padding),
    y1 = Math.min(n - 1, Math.ceil(ty(bounds[1]) - 1e-9) - 1 + padding)
  if ((x1 - x0 + 1) * (y1 - y0 + 1) > 256)
    throw new Error('Region needs too many detailed tiles; choose a smaller area.')
  const tiles = []
  for (let y = y0; y <= y1; y++) for (let x = x0; x <= x1; x++) tiles.push({ z, x, y })
  return tiles
}
async function response(url, signal) {
  signal?.throwIfAborted()
  const requestSignal = signal ? AbortSignal.any([signal, AbortSignal.timeout(30000)]) : AbortSignal.timeout(30000)
  const r = await fetch(url, { signal: requestSignal })
  if (!r.ok) throw new Error('Building data request failed (HTTP ' + r.status + '). Check source access and token.')
  return r
}
function authorizedUrl(value, accessToken) {
  const url = new URL(value, globalThis.location?.href ?? 'http://localhost/')
  if (!['https:', 'http:'].includes(url.protocol)) throw new Error('Unsupported building source URL.')
  if ((url.hostname === 'api.mapbox.com' || url.hostname.endsWith('.mapbox.com')) && accessToken)
    url.searchParams.set('access_token', accessToken)
  return url.href
}
/** Download/decode the complete bbox at source detail. Failed tiles are never silently treated as empty ground. */
export async function loadRegionTiles({
  sourceConfig,
  source,
  bounds,
  accessToken,
  signal,
  onProgress,
  paddingTiles = 0,
}) {
  if (!sourceConfig) throw new Error('The selected basemap does not provide this building source.')
  let metadata = sourceConfig
  if (sourceConfig.url) {
    let url = sourceConfig.url
    if (url.startsWith('mapbox://')) {
      const id = url.slice(9)
      if (!/^[\w.-]+(?:,[\w.-]+)*$/.test(id)) throw new Error('Invalid Mapbox tileset ID.')
      url = 'https://api.mapbox.com/v4/' + id + '.json?secure'
    }
    metadata = await (await response(authorizedUrl(url, accessToken), signal)).json()
  }
  if (!metadata.tiles?.length) throw new Error('The selected source has no vector tile URLs.')
  const z = Math.max(metadata.minzoom ?? 0, Math.min(16, metadata.maxzoom ?? 16))
  if (!Number.isInteger(z) || z < 0 || z > 22) throw new Error('Unsupported tile detail level.')
  const tiles = tileCoordinates(bounds, z, paddingTiles),
    features = []
  let next = 0,
    done = 0,
    bytes = 0
  const layerName = source === 'osm' ? 'building' : 'Montreal_Qatar-6hvjju'
  await Promise.all(
    Array.from({ length: Math.min(4, tiles.length) }, async () => {
      while (next < tiles.length) {
        const { x, y, z } = tiles[next++]
        let url = metadata.tiles[0]
          .replaceAll('{z}', String(z))
          .replaceAll('{x}', String(x))
          .replaceAll('{y}', String(metadata.scheme === 'tms' ? 2 ** z - y - 1 : y))
          .replaceAll('{ratio}', '')
        url = authorizedUrl(url, accessToken)
        const data = await (await response(url, signal)).arrayBuffer()
        bytes += data.byteLength
        if (data.byteLength > 16 * 1024 * 1024 || bytes > 96 * 1024 * 1024)
          throw new Error('Building tile data is too large for this browser. Select a smaller region.')
        const layer = new VectorTile(new PbfReader(new Uint8Array(data))).layers[layerName]
        if (layer)
          for (let i = 0; i < layer.length; i++) {
            const feature = layer.feature(i)
            if (source === 'osm' && String(feature.properties.extrude) !== 'true') continue
            if (feature.type === 3) features.push(feature.toGeoJSON(x, y, z))
          }
        done++
        onProgress?.(done / tiles.length)
      }
    }),
  )
  signal?.throwIfAborted()
  const n = 2 ** z,
    longitude = (x) => (x / n) * 360 - 180
  const latitude = (y) => (Math.atan(Math.sinh(Math.PI * (1 - (2 * y) / n))) * 180) / Math.PI
  const coverageBounds = [
    longitude(Math.min(...tiles.map((t) => t.x))),
    latitude(Math.max(...tiles.map((t) => t.y)) + 1),
    longitude(Math.max(...tiles.map((t) => t.x)) + 1),
    latitude(Math.min(...tiles.map((t) => t.y))),
  ]
  return { features, zoom: z, tileCount: tiles.length, coverageBounds }
}
