import { BufferAttribute, BufferGeometry, Mesh } from 'three'
import { STLExporter } from 'three/addons/exporters/STLExporter.js'

/**
 * Frozen MDDF height grid -> model ZIP members, without another map query or GPU read.
 * Input: 4m cells, layers counting 1.5m roof heights; e.g. [1,2] -> adjacent 1.5m/3m blocks.
 * Output: binary STL in metres (X east, Y up, Z south), metadata and the original map anchor.
 */
export async function buildModelFiles(input, grid, control = {}) {
  if (
    !grid ||
    !Number.isInteger(grid.nx) ||
    !Number.isInteger(grid.ny) ||
    grid.nx < 1 ||
    grid.ny < 1 ||
    grid.spacingM !== 4 ||
    grid.layerSpacingM !== 1.5 ||
    grid.layers?.length !== grid.nx * grid.ny
  )
    throw new Error('Invalid MDDF height grid.')
  const { nx, ny, layers, spacingM, layerSpacingM } = grid
  const level = (x, y) => (x < 0 || y < 0 || x >= nx || y >= ny ? 0 : layers[y * nx + x])
  const checkpoint = async () => {
    await new Promise((resolve) => setTimeout(resolve, 0))
    if (control.shouldCancel?.()) throw new Error('Model export cancelled.')
  }
  let faces = 0
  for (let y = 0; y < ny; y++) {
    if (y % 32 === 0) await checkpoint()
    for (let x = 0; x < nx; x++) {
      const h = level(x, y)
      if (!Number.isInteger(h) || h < 0 || h > 160) throw new Error('Invalid MDDF building height.')
      if (!h) continue
      faces +=
        2 +
        Number(h > level(x - 1, y)) +
        Number(h > level(x + 1, y)) +
        Number(h > level(x, y - 1)) +
        Number(h > level(x, y + 1))
    }
  }
  if (!faces) throw new Error('The selected MDDF model has no buildings to export.')
  // shortcut: grid faces are not merged; use greedy surface meshing if large model downloads become too costly.
  const positions = new Float32Array(faces * 18)
  let offset = 0
  const quad = (a, b, c, d) => {
    for (const point of [a, b, c, a, c, d]) {
      positions.set(point, offset)
      offset += 3
    }
  }
  for (let y = 0; y < ny; y++) {
    if (y % 32 === 0) await checkpoint()
    for (let x = 0; x < nx; x++) {
      const h = level(x, y) * layerSpacingM
      if (!h) continue
      const x0 = x * spacingM,
        x1 = x0 + spacingM,
        z0 = -y * spacingM,
        z1 = z0 - spacingM
      quad([x0, h, z0], [x1, h, z0], [x1, h, z1], [x0, h, z1])
      quad([x0, 0, z0], [x0, 0, z1], [x1, 0, z1], [x1, 0, z0])
      // Exposed step walls start at the neighbor's roof; internal shared walls are omitted.
      let b = level(x - 1, y) * layerSpacingM
      if (h > b) quad([x0, b, z1], [x0, b, z0], [x0, h, z0], [x0, h, z1])
      b = level(x + 1, y) * layerSpacingM
      if (h > b) quad([x1, b, z0], [x1, b, z1], [x1, h, z1], [x1, h, z0])
      b = level(x, y - 1) * layerSpacingM
      if (h > b) quad([x0, b, z0], [x1, b, z0], [x1, h, z0], [x0, h, z0])
      b = level(x, y + 1) * layerSpacingM
      if (h > b) quad([x1, b, z1], [x0, b, z1], [x0, h, z1], [x1, h, z1])
    }
  }
  const geometry = new BufferGeometry()
  geometry.setAttribute('position', new BufferAttribute(positions, 3))
  const mesh = new Mesh(geometry)
  let stl
  try {
    stl = new STLExporter().parse(mesh, { binary: true }).buffer
  } finally {
    geometry.dispose()
    mesh.material.dispose()
  }
  return [
    { name: 'mddf-model.stl', content: stl },
    {
      name: 'positionSetting.txt',
      content: JSON.stringify(
        {
          type: 'Feature',
          properties: { projection: 'local', note: 'STL origin (0,0,0) in WGS84' },
          geometry: { type: 'Point', coordinates: grid.origin },
        },
        null,
        2,
      ),
    },
    {
      name: 'metadata.json',
      content: JSON.stringify(
        {
          schemaVersion: 1,
          source: input.source,
          origin: grid.origin,
          projection: 'local equirectangular metres at origin',
          units: 'metres',
          axes: { x: 'east', y: 'up', z: 'south' },
          grid: { nx, ny, spacingM, layerSpacingM, extentM: grid.extentM },
          geometry: 'Exposed surfaces of the raster height grid supplied to MDDF, not the original vector footprints.',
          warnings: input.warnings,
          files: { 'mddf-model.stl': { format: 'binary-stl', triangles: faces * 2 } },
        },
        null,
        2,
      ),
    },
  ]
}
