import booleanIntersects from '@turf/boolean-intersects'
import union from '@turf/union'
import { coordEach } from '@turf/meta'
import { makeProjector, makeUnprojector } from '../../preprocessing/stl-converter/geojsonToStl.js'

/** Two WGS84 corners -> a southwest-anchored rectangle snapped to 4m cells before any feature query. */
export function createRegion(a, b) {
  for (const p of [a, b])
    if (
      !Array.isArray(p) ||
      p.length < 2 ||
      !p.every(Number.isFinite) ||
      Math.abs(p[0]) > 180 ||
      Math.abs(p[1]) > 85.051129
    )
      throw new Error('Invalid WGS84 region coordinates.')
  const origin = [Math.min(a[0], b[0]), Math.min(a[1], b[1])]
  if (Math.abs(a[0] - b[0]) >= 180) throw new Error('Region cannot cross the antimeridian (180 degrees).')
  const project = makeProjector(origin),
    unproject = makeUnprojector(origin)
  const [w, h] = project([Math.max(a[0], b[0]), Math.max(a[1], b[1])])
  if (w <= 0 || h <= 0) throw new Error('The region is empty.')
  const nx = Math.ceil((w - 1e-6) / 4),
    ny = Math.ceil((h - 1e-6) / 4)
  const ne = unproject([nx * 4, ny * 4])
  const bounds = [...origin, ...ne]
  const [west, south, east, north] = bounds
  const polygon = {
    type: 'Feature',
    properties: {},
    geometry: {
      type: 'Polygon',
      coordinates: [
        [
          [west, south],
          [east, south],
          [east, north],
          [west, north],
          [west, south],
        ],
      ],
    },
  }
  return { origin, bounds, extentM: [nx * 4, ny * 4], polygon }
}

/** Same provider identity priority as City's STL capture; zero remains a valid identifier. */
export function buildingId(feature) {
  const p = feature.properties ?? {},
    id = p.nd ?? p.osm_id ?? feature.id ?? p.id ?? p.auto_id
  return (typeof id === 'string' && id.trim() !== '') || (typeof id === 'number' && Number.isFinite(id))
    ? String(id)
    : null
}

/** Tile features -> unique whole provider parts; roof/base groups retain holes and distinct elevations. */
export function mergeBuildingParts(features) {
  const groups = new Map(),
    seen = new Set()
  for (const raw of features) {
    if (!['Polygon', 'MultiPolygon'].includes(raw.geometry?.type)) continue
    coordEach(raw, (p) => {
      if (!Number.isFinite(p[0]) || !Number.isFinite(p[1]) || Math.abs(p[0]) > 180 || Math.abs(p[1]) > 85.051129)
        throw new Error('Invalid building coordinates.')
    })
    const height = Number(raw.properties?.height),
      base = Number(raw.properties?.min_height) || 0
    const geometryKey = JSON.stringify([raw.geometry, height, base])
    if (seen.has(geometryKey)) continue
    seen.add(geometryKey)
    // shortcut: without a provider ID, only exact duplicates can be removed; use provider footprints for cross-tile identity.
    const id = buildingId(raw),
      key = id == null ? geometryKey : JSON.stringify([id, height, base])
    if (!groups.has(key)) groups.set(key, [])
    // Mapbox geometry can be a prototype getter; clone the public GeoJSON fields explicitly.
    groups.get(key).push({
      type: 'Feature',
      ...(raw.id == null ? {} : { id: raw.id }),
      properties: structuredClone(raw.properties ?? {}),
      geometry: structuredClone(raw.geometry),
    })
  }
  return Array.from(groups.values(), (parts) => {
    const feature = parts[0]
    if (parts.length > 1) {
      const merged = union({ type: 'FeatureCollection', features: parts })
      if (!merged) throw new Error('Building parts produced empty geometry.')
      feature.geometry = merged.geometry
      delete feature.bbox
    }
    return feature
  })
}

/**
 * One tileset + drawn region -> whole selected buildings, remaining parts, and a fitted 4m domain.
 * Touching the drawn edge selects the whole provider ID, including its other roof parts.
 * The fitted rectangle never selects extra neighbors. Empty inputs keep the drawn open-ground domain.
 */
export function selectBuildings(features, region) {
  const parts = mergeBuildingParts(features),
    mask = region.selection ?? region.polygon
  const touching = new Set(parts.filter((f) => booleanIntersects(f, mask)))
  const ids = new Set(Array.from(touching, buildingId).filter((id) => id != null))
  const selected = [],
    outside = [],
    warnings = []
  let skipped = 0,
    raised = 0
  for (const feature of parts) {
    if (!touching.has(feature) && !(buildingId(feature) != null && ids.has(buildingId(feature)))) {
      outside.push(feature)
      continue
    }
    const value = feature.properties?.height
    if (value === undefined || value === null || value === '') {
      skipped++
      continue
    }
    const height = Number(value)
    if (!Number.isFinite(height) || height < 0 || height > 240)
      throw new Error('Building height must be finite and between 0 and 240 m.')
    if (height === 0) {
      skipped++
      continue
    }
    if (Number(feature.properties?.min_height) > 0) raised++
    selected.push({
      ...feature,
      properties: {
        ...feature.properties,
        source_height: height,
        source_min_height: Number(feature.properties?.min_height) || 0,
        height: Math.max(1, Math.round(height / 1.5)) * 1.5,
        min_height: 0,
      },
    })
  }
  const buildings = { type: 'FeatureCollection', features: selected }
  let fitted = region
  if (selected.length) {
    const bounds = [Infinity, Infinity, -Infinity, -Infinity]
    coordEach(buildings, (p) => {
      bounds[0] = Math.min(bounds[0], p[0])
      bounds[1] = Math.min(bounds[1], p[1])
      bounds[2] = Math.max(bounds[2], p[0])
      bounds[3] = Math.max(bounds[3], p[1])
    })
    fitted = createRegion(bounds.slice(0, 2), bounds.slice(2, 4))
  }
  if (skipped) warnings.push(skipped + ' parts have missing/zero height and were omitted.')
  if (raised) warnings.push(raised + ' raised parts are treated as solid from the ground to their roof.')
  if (!selected.length) warnings.push('No buildings found in loaded map data. This run will use open ground.')
  if (selected.some((f) => buildingId(f) == null))
    warnings.push('Selected parts without provider IDs cannot be joined across tile boundaries.')
  warnings.push('Loaded map tiles only; this is not a complete OSM database extract.')
  return {
    ...structuredClone(region),
    ...fitted,
    selection: structuredClone(region.selection ?? region.polygon),
    buildings,
    surroundings: { type: 'FeatureCollection', features: outside },
    warnings,
  }
}

/** Free polygon -> original selection plus a snapped rectangular FLUME domain with open-ground padding. */
export function createPolygonRegion(feature) {
  if (feature?.geometry?.type !== 'Polygon') throw new Error('Draw a valid polygon first.')
  const bounds = [Infinity, Infinity, -Infinity, -Infinity]
  let count = 0
  coordEach(feature, (p) => {
    if (!Number.isFinite(p[0]) || !Number.isFinite(p[1])) throw new Error('Invalid polygon coordinates.')
    bounds[0] = Math.min(bounds[0], p[0])
    bounds[1] = Math.min(bounds[1], p[1])
    bounds[2] = Math.max(bounds[2], p[0])
    bounds[3] = Math.max(bounds[3], p[1])
    count++
  })
  if (count < 4) throw new Error('A polygon needs at least three corners.')
  const region = createRegion(bounds.slice(0, 2), bounds.slice(2, 4))
  return { ...region, selection: { type: 'Feature', properties: {}, geometry: structuredClone(feature.geometry) } }
}
