/** User values in metres/degrees/m/s -> validated, cell-centred FLUME settings. Direction means wind TOWARDS. */
export function normalizeWindSettings({ heightM, directionDeg, speedMps }) {
  const number = (value, name) => {
    if (value === '' || value === null || value === undefined || !Number.isFinite(Number(value)))
      throw new Error('Invalid ' + name + '.')
    return Number(value)
  }
  const h = number(heightM, 'height'),
    d = number(directionDeg, 'direction'),
    speed = number(speedMps, 'speed')
  if (h < 0.75 || h > 239.25) throw new Error('Height must be between 0.75 and 239.25 m.')
  if (speed < 0.5 || speed > 20) throw new Error('Wind speed must be between 0.5 and 20 m/s.')
  const layerIndex = Math.max(0, Math.min(159, Math.round(h / 1.5 - 0.5))),
    direction = ((d % 360) + 360) % 360
  return {
    layerIndex,
    heightM: (layerIndex + 0.5) * 1.5,
    directionDeg: direction,
    thetaRad: (direction * Math.PI) / 180,
    speedMps: speed,
  }
}
